function makeStockReport(products) {
  const activeProducts = products.filter((product) => product.stock > 0);
  const names = activeProducts.map((product) => product.name);
  const totalValue = activeProducts.reduce((total, product) => total + product.price * product.stock, 0);
  return { names, totalValue };
}
